// Delete order respects FK graph (children first). FKs on SET NULL/CASCADE make
// this forgiving, but we keep it explicit so it stays predictable.
const TRUNCATE_ORDER = [
	'document_chunks',
	'review_records',
	'issue_comments',
	'issue_status_logs',
	'civic_issues',
	'flagged_claims',
	'processed_content',
	'raw_content',
	'lgu_documents',
	'nlp_categories'
] as const;

const NEVER_MATCH = '00000000-0000-0000-0000-000000000000';

async function truncateTables(svc: SupabaseClient): Promise<void> {
	for (const table of TRUNCATE_ORDER) {
		const { error } = await (svc.from(table) as any).delete().neq('id', NEVER_MATCH);
		if (error) throw new Error(`truncate ${table}: ${error.message}`);
	}
}

/**
 * True when `account`'s expected password already works for an existing user.
 *
 * Uses a throwaway anon client rather than the service-role client: GoTrue
 * exposes no admin-side password verification, so signing in is the only way
 * to check. The probe session it creates is signed straight back out so the
 * probe never leaves a stray live refresh token behind.
 */
async function passwordAlreadyWorks(
	local: LocalSupabase,
	account: { email: string; password: string }
): Promise<boolean> {
	const probe = createClient(local.url, local.anonKey, {
		auth: { persistSession: false, autoRefreshToken: false }
	});
	const { error } = await probe.auth.signInWithPassword({
		email: account.email,
		password: account.password
	});
	if (!error) await probe.auth.signOut({ scope: 'local' });
	return !error;
}

async function upsertUser(
	svc: SupabaseClient,
	local: LocalSupabase,
	account: { email: string; password: string; name: string; role: string }
): Promise<string> {
	const { data: existing } = await svc.auth.admin.listUsers({ perPage: 200 });
	const found = existing?.users.find((u) => u.email === account.email);

	let id: string;
	if (found) {
		id = found.id;

		// Resetting a password through the admin API deletes every row in
		// `auth.sessions` for that user, which silently kills the refresh token
		// baked into `tests/e2e/.auth/*.json` by an earlier run — a later page
		// load then fails with "Invalid Refresh Token: Refresh Token Not Found".
		// Only pay that cost when the stored password is actually wrong.
		//
		// A metadata-only update does NOT revoke sessions, so `role` and
		// `full_name` can still be re-synced on every seed for free.
		if (await passwordAlreadyWorks(local, account)) {
			await svc.auth.admin.updateUserById(id, {
				email_confirm: true,
				app_metadata: { role: account.role },
				user_metadata: { full_name: account.name }
			});
		} else {
			await svc.auth.admin.updateUserById(id, {
				password: account.password,
				email: account.email,
				email_confirm: true,
				app_metadata: { role: account.role },
				user_metadata: { full_name: account.name }
			});
		}
	} else {
		const { data, error } = await svc.auth.admin.createUser({
			email: account.email,
			password: account.password,
			email_confirm: true,
			app_metadata: { role: account.role },
			user_metadata: { full_name: account.name }
		});
		if (error) throw new Error(`createUser ${account.email}: ${error.message}`);
		id = data.user.id;
	}

	const { error: profileError } = await (svc.from('profiles') as any).upsert({
		id,
		full_name: account.name,
		role: account.role,
		password_set: true
	});
	if (profileError) throw new Error(`upsert profile ${account.email}: ${profileError.message}`);

	return id;
}

// pgvector literal for a 768-dim column. Passing the JSON array directly is
// unreliable — send the canonical '[0.5,...]' string the vector input parser
// expects.
function vec(fill: number): string {
	return `[${Array.from({ length: 768 }, () => String(fill)).join(',')}]`;
}

